/* HEXA BATTLEGROUNDS upgrade — PART 1 OF 6. Only for databases that already ran setup part-01…; run in order. Safe to re-run. */ alter table events add column if not exists is_trial boolean not null default false; alter table arenas add column if not exists match_phase int not null default 0; alter table arenas add column if not exists phase_started_at timestamptz; alter table arenas add column if not exists phase_next_at timestamptz; alter table arenas add column if not exists zone_hold boolean not null default false; create or replace function _defaults() returns jsonb language sql immutable as $$ select jsonb_build_object( 'pts_standard', 100, 'pts_hard', 150, 'pts_battle', 125, 'pts_airdrop', 75, 'pts_relay_bonus', 25, 'pts_relocation', 40, 'pen_recovery', 40, 'finale_max', 300, 'finale_entry_max', 200, 'finale_exchange_max', 200, 'hp_max', 100, 'hp_respawn', 50, 'dmg_fail', 10, 'dmg_zone', 15, 'shield_max', 60, 'shuttle_seconds', 10, 'roles_seconds', 15, 'bus_size', 3, 'arena_size', 15, 'attack_cooldown', 90, 'protect_seconds', 120, 'recovery_seconds', 120, 'zone_warning', 60, 'airdrop_window', 180, 'airdrop_interval', 0, 'intel_fallback', 90, 'relay_chance', 20, 'hint_cost', 15, 'alliance_minutes', 10, 'alliance_cost', 10, 'chat_limit', 6, 'drop_seconds', 8, 'visit_missions', 2, 'zone_auto', 0, 'zone_schedule', '20,40,55,70,85', 'sync_seconds', 0, 'auto_pacing', 0, 'phase_schedule', '2,12,30,50', 'duel_phase', 2, 'mission_time_pct', 100, 'pin_length', 6 ) $$; create or replace function _phase_zone_target(p_phase int) returns int language sql immutable as $$ select (array[0, 0, 1, 3, 4, 5])[least(5, greatest(0, p_phase)) + 1] $$; create or replace function _new_pin(p_len int) returns text language plpgsql volatile as $$ declare v text := ''; begin p_len := least(8, greatest(4, coalesce(p_len, 6))); while length(v) < p_len loop v := v || ((('x' || substr(replace(gen_random_uuid()::text, '-', ''), 1, 12))::bit(48)::bigint) % 10)::text; end loop; return v; end $$; create or replace function _weak_pin(p text) returns boolean language sql immutable as $$ select p !~ '^[0-9]{4,8}$' or p ~ '^(.)\1+$' or position(p in '01234567890') > 0 or position(p in '98765432109') > 0 $$; create or replace function _set_match_phase(p_arena uuid, p_phase int) returns void language plpgsql as $$ declare a arenas; e events; v_next timestamptz; v_sched text[]; v_min int; begin select * into a from arenas where id = p_arena for update; select * into e from events where id = a.event_id; p_phase := greatest(0, least(5, p_phase)); if p_phase < 4 and _cfg(a.event_id, 'auto_pacing') = 1 and a.play_started_at is not null then v_sched := string_to_array(_cfg_text(a.event_id, 'phase_schedule'), ','); begin v_min := nullif(trim(v_sched[p_phase + 1]), '')::int; exception when others then v_min := null; end; if v_min is not null then v_next := greatest(now() + interval '5 seconds', a.play_started_at + make_interval(mins => v_min)); end if; end if; update arenas set match_phase = p_phase, phase_started_at = now(), phase_next_at = v_next, zone_hold = false, overlay = overlay || jsonb_build_object('match', jsonb_build_object( 'phase', p_phase, 'started_at', now(), 'next_at', v_next, 'duel_phase', _cfg(a.event_id, 'duel_phase'), 'zone_target', _phase_zone_target(p_phase)), 'trial', e.is_trial) where id = p_arena; if a.match_phase is distinct from p_phase or a.phase_started_at is null then perform _feed(p_arena, 'phase.started', jsonb_build_object('phase', p_phase)); end if; perform _ping_arena(p_arena, 'phase'); end $$; create or replace function _battles_phase_guard() returns trigger language plpgsql as $$ declare a arenas; begin select * into a from arenas where id = new.arena_id; if a.match_phase < _cfg(a.event_id, 'duel_phase') then raise exception 'DUELS_LOCKED'; end if; return new; end $$; drop trigger if exists battles_phase_guard on battles; create trigger battles_phase_guard before insert on battles for each row execute function _battles_phase_guard(); create or replace function _teams_defaults() returns trigger language plpgsql as $$ declare v_n int; begin if new.name is null or new.name = '' or new.name = 'Squad ' || new.number then new.name := (array['Alpha','Bravo','Charlie','Delta','Echo','Foxtrot','Golf','Hotel','India','Juliet','Kilo','Lima', 'Mike','November','Oscar','Papa','Quebec','Romeo','Sierra','Tango','Uniform','Victor','Whiskey','Xray','Yankee','Zulu']) [1 + (new.number - 1) % 26] || '-' || lpad(new.number::text, 2, '0'); end if; if new.bus is null then select count(*) into v_n from teams where arena_id = new.arena_id; new.bus := 1 + v_n / greatest(1, _cfg(new.event_id, 'bus_size')); end if; return new; end $$; drop trigger if exists teams_defaults on teams; create trigger teams_defaults before insert on teams for each row execute function _teams_defaults(); create or replace function _pick_template(p_team uuid, p_kind text, p_tags text[]) returns text language plpgsql stable as $$ declare t teams; v_seed int; v text; v_phase int; begin select * into t from teams where id = p_team; select mission_seed into v_seed from events where id = t.event_id; select match_phase into v_phase from arenas where id = t.arena_id; select mt.id into v from mission_templates mt where mt.kind = p_kind and mt.status = 'published' and not exists (select 1 from mission_instances mi where mi.team_id = p_team and mi.template_id = mt.id) order by (mt.tags && coalesce(p_tags, '{}')) desc, (case when coalesce(v_phase, 0) <= 1 then mt.difficulty <= 1 when v_phase >= 3 then mt.difficulty >= 2 else true end) desc, md5(v_seed::text || p_team::text || mt.id || t.mission_counter::text) limit 1; if v is null then select mt.id into v from mission_templates mt where mt.kind = p_kind and mt.status = 'published' order by (mt.tags && coalesce(p_tags, '{}')) desc, md5(v_seed::text || p_team::text || mt.id || t.mission_counter::text) limit 1; end if; return v; end $$;
